per_hop.query:
SELECT ?person ?sport ?origin WHERE {
  {
    VALUES ?person { wd:Q123 (replace with Angelique Kerber's Wikidata QID) }
    ?person wdt:P641 ?sport .
    OPTIONAL { ?person wdt:P27 ?origin. }
  }
  UNION
  {
    ?event wdt:P31 wd:Q847017 ;  # tennis tournament
           rdfs:label "2005 China Open – Men's Doubles"@en ;
           wdt:P1346 ?defendingChampion.
    ?defendingChampion wdt:P641 ?sport.
    OPTIONAL { ?defendingChampion wdt:P27 ?origin. }
  }
}

